// Кейс: .qa/tests/monitoring/MON-036.md шаг 3 · план: .qa/e2e-app/specs/app.md (1.58)
// Pixel свёрнут (Home), пока на iPhone заканчивается мониторинг; возврат в приложение без перезапуска → новая строка первой в «ניטורים אחרונים» сразу
// (в пределах BANCI_RECENT_SEC). ЗАПУСКАЕТ МОНИТОРИНГ — BANCI_MONITORING=1 + BANCI_ANDROID_SERIAL.
import { assert } from '../../lib/appium.mjs';
import { startMonitoring, endMonitoring, waitTimer } from '../../lib/monitoring.mjs';
import { requireSecondPhone, pixelHome, pixelBackground, pixelForeground, recentRows, waitNewRow, RECENT } from '../../lib/second-phone.mjs';

export const name = '«ניטורים אחרונים» на втором телефоне: сеанс закончился, пока Pixel в фоне → возврат → новая строка первой сразу #7f31a2 @iphone @app @data';

export default async function (app) {
  const pixel = await requireSecondPhone();
  await pixelHome(pixel);
  const before = await recentRows(pixel);

  await startMonitoring(app);
  await waitTimer(app, 20);
  await pixelBackground(pixel);
  await endMonitoring(app);

  await pixelForeground();
  await pixel.waitFor(RECENT, { timeout: 20000, what: 'Pixel: «בית» после возврата из фона' });
  const { rows, row, sec } = await waitNewRow(pixel, before);
  console.log(`     после возврата из фона новая строка через ${sec.toFixed(1)} с: ${row}`);
  assert(rows[0] === row, `новая строка «${row}» — первая в списке (сейчас сверху: ${rows[0]})`);
  assert(rows.filter((r) => r === row).length === 1, 'новая строка не задвоена');
}
